components.css:
.model-nav{--border:#dce3ef;--ease-out:cubic-bezier(.16,1,.3,1);font:600 13px/1.35 "Segoe UI",sans-serif}.model-nav button{display:inline-flex;align-items:center;cursor:pointer;box-sizing:border-box}.model-nav { --nav-inset: 5px; --nav-gap: 4px; --model-index: 0; position: relative; isolation: isolate; display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); margin-bottom: 24px; padding: var(--nav-inset); border: 1px solid var(--border); border-radius: 11px; background: #eaf0f8; gap: var(--nav-gap); }
.model-nav[data-model=nfa] { --model-index: 1; }
.model-nav[data-model=pda] { --model-index: 2; }
.model-nav[data-model=tm] { --model-index: 3; }
.model-nav::before { box-sizing: border-box; content: ''; position: absolute; z-index: -1; inset-block: var(--nav-inset); left: var(--nav-inset); width: calc((100% - 2 * var(--nav-inset) - 3 * var(--nav-gap)) / 4); border: 1px solid #cbd8ef; border-radius: 7px; background: #fff; box-shadow: 0 2px 4px #21355706; transform: translateX(calc(var(--model-index) * (100% + var(--nav-gap)))); transition: transform 220ms var(--ease-out); pointer-events: none; }
.model-nav button { justify-content: flex-start; gap: 12px; padding: 9px 16px; min-height: 48px; background: transparent; border: 1px solid transparent; color: #536276; border-radius: 7px; transition: color 140ms ease, background-color 140ms ease; }
.model-nav button.active { color: #194bc8; background: transparent; }
.model-abbr { font-size: 15px; font-weight: 750; letter-spacing: -.015em; }
.model-description { text-align: left; font-size: 12px; font-weight: 400; }
@media(max-width:600px){.model-nav{--nav-inset:4px;--nav-gap:3px}.model-nav button{min-height:44px;padding:8px 5px;justify-content:center}}@media(prefers-reduced-motion:reduce){.model-nav::before,.model-nav button{transition:none}}.model-nav button:focus-visible{outline:3px solid #376be7;outline-offset:3px}
